-- P5: Postgres row-level security as a second tenant-isolation layer.
-- API requests run with app.tenant_id = token tenant (set per transaction); rows of other tenants are
-- invisible and cannot be written. Workers/scheduler run in system context (app.tenant_id unset/empty).
-- FORCE applies the policy to the table owner too; deploy the engine as a non-superuser role.
ALTER TABLE flow_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE flow_sources FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON flow_sources;
CREATE POLICY tenant_isolation ON flow_sources USING (coalesce(current_setting('app.tenant_id', true), '') = '' OR tenant_id = current_setting('app.tenant_id', true)) WITH CHECK (coalesce(current_setting('app.tenant_id', true), '') = '' OR tenant_id = current_setting('app.tenant_id', true));
ALTER TABLE flow_source_cursors ENABLE ROW LEVEL SECURITY;
ALTER TABLE flow_source_cursors FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON flow_source_cursors;
CREATE POLICY tenant_isolation ON flow_source_cursors USING (coalesce(current_setting('app.tenant_id', true), '') = '' OR tenant_id = current_setting('app.tenant_id', true)) WITH CHECK (coalesce(current_setting('app.tenant_id', true), '') = '' OR tenant_id = current_setting('app.tenant_id', true));
